function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`}
const brandPreview=false;
const brandName='vokiri';
const brandMark=()=>'<img src="./brand/mark.svg" alt="">';
const brandLockup=()=>'<span class="brand-lockup"><img class="vokiri-wordmark" src="./brand/wordmark.svg" alt="Vokiri"><small>PERSONAL ENGLISH</small></span>';
document.body.classList.add('brand-preview');document.title='Vokiri — Personal English';
const seed=()=>DICTIONARY.slice(0,24).map(w=>({...w}));
let state;try{state=JSON.parse(localStorage.getItem('english-hub-v1'))}catch{}
if(!state||!Array.isArray(state.words)||!state.words.every(w=>w&&typeof w.word==='string'&&typeof w.id==='string'))state={words:seed(),reviewed:[],read:[]};
state.reviewed??=[];state.read??=[];
let screen='today',filter='All',query='',group='All groups',sort='A–Z',modal=null,session=null,topic='Mind & life',duration=5,articleOpen=false,importMode='paste',importPreview=null,translationResult=null,translateInput='',language='en',lastFocus=null;
const wordById=id=>state.words.find(w=>w.id===id)||DICTIONARY.find(w=>w.id===id);
const lookup=s=>DICTIONARY.find(w=>w.word.toLowerCase()===s.trim().toLowerCase())||state.words.find(w=>w.word.toLowerCase()===s.trim().toLowerCase());
const todayKey=()=>MemoryModel.key(Date.now());
const dailyLimit=()=>state.profile?.dailyGoal||20;
state.words=state.words.map(w=>MemoryModel.migrate(w));
state.readingLevel=['A2','B1','B2'].includes(state.readingLevel)?state.readingLevel:'B1';
state.schemaVersion=2;
state.profile??={name:'Kirill',dailyGoal:20,reminder:true,reminderTime:'19:00'};
state.profile.activityWeeks=[12,52].includes(state.profile.activityWeeks)?state.profile.activityWeeks:52;
if(!Array.isArray(state.activity)||state.activityVersion!==2){const demo=new Map(seedActivity().map(day=>[day.date,day]));for(const day of state.activity||[])demo.set(day.date,day);state.activity=[...demo.values()];state.activityVersion=2}
touchToday();
const dailyReviewedIds=()=>new Set(state.reviewed.filter(r=>r.day===todayKey()&&r.mode!=='free').map(r=>r.id));
const dailyRemaining=()=>Math.max(0,dailyLimit()-dailyReviewedIds().size);
const dailyQueue=()=>[...state.words].filter(w=>!dailyReviewedIds().has(w.id)&&(w.status==='New'||w.memory.dueAt<=Date.now())).sort((a,b)=>(b.status==='New'&&b.addedAt>100)-(a.status==='New'&&a.addedAt>100)||a.memory.dueAt-b.memory.dueAt).slice(0,dailyRemaining());
const dueWords=()=>dailyQueue().filter(w=>w.status!=='New');
function dayAtOffset(offset){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-offset);return MemoryModel.key(d)}
function seedActivity(){return Array.from({length:364},(_,i)=>363-i).filter(offset=>offset<4||(offset!==4&&offset%6!==0&&offset%11!==0)).map(offset=>({date:dayAtOffset(offset),visits:1,reviews:(offset*7+3)%18,wordsAdded:offset%9===0?2:offset%4===0?1:0,textsRead:offset%8===0?1:0}))}
function touchToday(){const key=todayKey(),entry=state.activity.find(day=>day.date===key);if(entry){entry.visits=Math.max(1,entry.visits||0);entry.lastOpenedAt=Date.now()}else state.activity.push({date:key,visits:1,reviews:0,wordsAdded:0,textsRead:0,lastOpenedAt:Date.now()})}
function activityDates(){return [...new Set(state.activity.map(day=>day.date))].sort()}
function currentStreak(){const days=new Set(activityDates());let d=new Date();d.setHours(12,0,0,0);if(!days.has(MemoryModel.key(d)))d.setDate(d.getDate()-1);let streak=0;while(days.has(MemoryModel.key(d))){streak++;d.setDate(d.getDate()-1)}return streak}
function longestStreak(){let best=0,run=0,previous=null;for(const key of activityDates()){const current=new Date(`${key}T12:00:00`);run=previous&&(current-previous)/MemoryModel.DAY===1?run+1:1;best=Math.max(best,run);previous=current}return best}
function activityScore(day){return (day?.visits||0)+(day?.reviews||0)+(day?.wordsAdded||0)*2+(day?.textsRead||0)*3}
function activityLevel(day){const score=activityScore(day);return !score?0:score<4?1:score<9?2:score<15?3:4}
function calendarDays(weeks=state.profile.activityWeeks){const today=new Date();today.setHours(12,0,0,0);const monday=new Date(today);monday.setDate(today.getDate()-((today.getDay()+6)%7)-(weeks-1)*7);return Array.from({length:weeks*7},(_,i)=>{const date=new Date(monday);date.setDate(monday.getDate()+i);return date})}
function calendarMonths(days){let previous='';return Array.from({length:days.length/7},(_,week)=>{const date=days[week*7+3],key=`${date.getFullYear()}-${date.getMonth()}`;if(key===previous)return '';previous=key;return `<span style="grid-column:${week+1} / span 4">${date.toLocaleDateString('ru-RU',{month:'short'}).replace('.','')}</span>`}).join('')}
function persist(){try{localStorage.setItem('english-hub-v1',JSON.stringify(state))}catch{toast('Хранилище недоступно. Прогресс сохранится только до закрытия страницы.')}}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3300)}
function badge(status){return `<span class="status ${status.toLowerCase()}">${esc(status)}</span>`}
function nav(mobile=false){return ['today','vocabulary','reading','translator'].map((v,i)=>`<a href="#${v}" class="${mobile?'':'nav-item '}${screen===v||screen==='review'&&v==='today'?'active':''}" ${screen===v?'aria-current="page"':''}>${mobile?'<span class="nav-icon">':''}${icon(['home','cards','book','translate'][i])}${mobile?'</span>':''}<span>${['Today','Vocabulary','Reading','Translator'][i]}</span></a>`).join('')}
function shell(content){$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${brandLockup()}</div><nav class="side-nav" aria-label="Main navigation">${nav()}</nav><div class="sidebar-footer"><strong>Your words. A little, daily.</strong><br>Личный словарь · локально${brandPreview?'<span class="preview-label">Brand concept 01</span>':''}</div></aside><main><div class="topline"><span class="date">${new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}).toUpperCase()}</span><div class="mobile-brand">${brandLockup()}</div><a href="#profile" class="profile ${screen==='profile'?'active':''}" aria-label="Open personal space" ${screen==='profile'?'aria-current="page"':''}>${esc((state.profile.name||'V').trim().charAt(0).toUpperCase())}</a></div><div class="page">${content}</div></main><nav class="mobile-nav" aria-label="Main navigation">${nav(true)}</nav></div>`}
function wordRow(w){return `<button class="word-row" data-action="word" data-id="${esc(w.id)}"><span class="word-info"><strong>${esc(w.word)}</strong><p>${esc(w.translation)}</p></span>${badge(w.status)}${icon('chevron')}</button>`}
const statusLabel=status=>({All:'Все',New:'Новые',Learning:'Изучаю',Weak:'Слабые',Familiar:'Знакомые'})[status]||status;
function wordTile(w){return `<button class="vocab-card" data-action="word" data-id="${esc(w.id)}"><span class="vocab-card-top"><span class="vocab-state ${w.status.toLowerCase()}"><i></i>${statusLabel(w.status)}</span>${icon('chevron')}</span><span class="vocab-card-copy"><strong>${esc(w.word)}</strong><span>${esc(w.translation)}</span></span><small>${esc(w.group||'Без группы')}</small></button>`}
function today(){const queue=dailyQueue(),count=queue.length,done=dailyReviewedIds().size,reading=getArticle('Mind & life');return `<div class="page-head"><div><h1>A little English,<br>every day.</h1><p>Вспоминать сегодня. Узнавать через время.</p></div></div><div class="today-grid"><section class="review-hero"><div class="card-top"><span class="eyebrow">${count?'Your daily review':'Daily session complete'}</span><span class="round-symbol">${icon('cards')}</span></div><div class="hero-number">${count}<span>words ${count?'for today':'left today'}</span></div><div class="dot-matrix" aria-hidden="true"></div><div class="review-breakdown">${count?`<span>${queue.filter(w=>w.status!=='New').length} к повторению</span><span>${queue.filter(w=>w.status==='New').length} новых</span>`:`<span>${done} слов повторено · можно продолжить свободно</span>`}</div><button class="primary full" data-action="${count?'review':'free-review'}">${count?'Start Review':'Free Practice'}${icon('arrow')}</button></section><section class="reading-teaser"><span class="pill">${icon('spark')} Today’s reading</span><h2>${reading.title}</h2><p class="meta">${state.readingLevel} · ~${readingMinutes(reading)} min read</p><div class="card-bottom"><p><strong>${articleWords(reading).length} words</strong> from your vocabulary</p><button class="icon-btn dark" aria-label="Start today’s reading" data-action="read-today">${icon('up')}</button></div></section></div><div class="practice-entry"><span>${count?`Дневной ориентир: до ${dailyLimit()} слов`:'Сегодняшняя сессия завершена'}</span><button class="text-btn" data-action="free-review">Free Practice ${icon('arrow')}</button></div><section class="english-moment" aria-label="Английский в контексте"><span class="eyebrow">A word in your world</span><p lang="en">At first, I was <button class="context-word" data-action="reading-word" data-value="reluctant" aria-label="Перевод reluctant">reluctant</button> to speak.</p><span class="context-hint">Нажмите на слово — узнайте его значение.</span></section><div class="quick-actions"><button class="quick-action" data-action="add"><span class="action-icon">${icon('plus')}</span>Quick Add ${icon('up')}</button><button class="quick-action" data-action="import"><span class="action-icon">${icon('import')}</span>Import words ${icon('up')}</button></div><div class="section-title"><h2>In your vocabulary</h2><a class="text-btn" href="#vocabulary">View all ${icon('arrow')}</a></div><div class="word-list">${[...state.words].sort((a,b)=>b.addedAt-a.addedAt).slice(0,3).map(wordRow).join('')}</div><p class="footer-note">ADD &nbsp;→&nbsp; LEARN &nbsp;→&nbsp; REVIEW &nbsp;→&nbsp; MEET AGAIN</p>`}
function profile(){const streak=currentStreak(),best=longestStreak(),weeks=state.profile.activityWeeks,activity=new Map(state.activity.map(day=>[day.date,day])),days=calendarDays(weeks),today=todayKey(),reviews=state.activity.reduce((sum,day)=>sum+(day.reviews||0),0)+state.reviewed.length,texts=state.activity.reduce((sum,day)=>sum+(day.textsRead||0),0)+state.read.length,initial=esc((state.profile.name||'V').trim().charAt(0).toUpperCase()),activeDays=activityDates().filter(key=>key>=MemoryModel.key(days[0])&&key<=today).length;const cells=days.map(date=>{const key=MemoryModel.key(date),day=activity.get(key),future=key>today,score=activityScore(day);return `<span class="activity-cell level-${future?0:activityLevel(day)} ${key===today?'today':''} ${future?'future':''}" title="${date.toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}: ${score} действий" aria-label="${date.toLocaleDateString('ru-RU')}: ${score} действий"></span>`}).join('');return `<div class="account-page"><div class="page-head account-heading"><div><span class="eyebrow">Vokiri profile</span><h1>Личный кабинет</h1><p>Ваш прогресс, активность и настройки в одном месте.</p></div></div><div class="account-hero"><section class="identity-card"><div class="identity-top"><span class="account-avatar">${initial}</span><button class="icon-btn light" data-action="edit-profile" aria-label="Изменить профиль">${icon('edit')}</button></div><div class="identity-copy"><span class="eyebrow">Профиль</span><h2>${esc(state.profile.name||'Vokiri learner')}</h2><p>Уровень чтения ${state.readingLevel}</p></div><div class="identity-note"><span>${icon('shield')}</span><p>Здесь хранятся ваши слова, история занятий и личные настройки.</p></div></section><section class="streak-card"><div class="streak-symbol">${icon('flame')}</div><span class="eyebrow">Текущая серия</span><div class="streak-number">${streak}<span>${streak===1?'день':'дня'}</span></div><p>${streak?`Вы возвращаетесь ${streak} ${streak===1?'день':'дня'} подряд. Сегодняшний день уже отмечен.`:'Серия начнётся после первого активного дня.'}</p><div class="best-streak"><span>Лучшая серия</span><strong>${best} дней</strong></div></section></div><section class="activity-card"><div class="activity-head activity-title-row"><div><span class="eyebrow">Активность</span><h2>Ваш учебный ритм</h2><p>Каждый квадрат — один день. Чем насыщеннее цвет, тем больше было практики.</p></div><div class="range-toggle" role="group" aria-label="Период календаря">${[[12,'3 месяца'],[52,'Год']].map(([value,label])=>`<button class="${weeks===value?'active':''}" data-action="activity-range" data-value="${value}" aria-pressed="${weeks===value}">${label}</button>`).join('')}</div></div><div class="activity-summary-line"><strong>${activeDays} активных дней</strong><span>${weeks===52?'за последний год':'за последние 3 месяца'}</span></div><div class="activity-calendar-shell"><div class="activity-weekdays" aria-hidden="true"><span>Пн</span><span></span><span>Ср</span><span></span><span>Пт</span><span></span><span>Вс</span></div><div class="activity-scroll" id="activity-scroll"><div class="activity-track weeks-${weeks}" style="--weeks:${weeks}"><div class="activity-months">${calendarMonths(days)}</div><div class="activity-grid" role="img" aria-label="Календарь активности">${cells}</div></div></div></div><div class="calendar-scroll-hint">← Листайте по месяцам · текущий месяц справа →</div><div class="activity-footer"><span>Входы · новые слова · повторения · чтение</span><span class="activity-legend" aria-label="Интенсивность активности"><small>Меньше</small><i class="level-0"></i><i class="level-1"></i><i class="level-2"></i><i class="level-3"></i><i class="level-4"></i><small>Больше</small></span></div></section><div class="account-bottom"><section class="progress-card"><div class="activity-head"><div><span class="eyebrow">Прогресс</span><h2>За всё время</h2></div>${icon('target')}</div><div class="profile-stats"><div><strong>${state.words.length}</strong><span>слов сохранено</span></div><div><strong>${reviews}</strong><span>повторений</span></div><div><strong>${texts}</strong><span>текстов прочитано</span></div></div><p class="profile-quiet">Серия помогает держать ритм, но одна пропущенная дата не стирает знания.</p></section><section class="preferences-card"><div class="activity-head"><div><span class="eyebrow">Настройки</span><h2>Под себя</h2></div></div><div class="preference-block"><div><strong>Слов в день</strong><small>Размер основной сессии повторения</small></div><div class="compact-options">${[10,20,30].map(n=>`<button class="option-pill ${state.profile.dailyGoal===n?'active':''}" data-action="daily-goal" data-value="${n}" aria-pressed="${state.profile.dailyGoal===n}">${n}</button>`).join('')}</div></div><div class="preference-block"><div><strong>Уровень текстов</strong><small>Сложность персонального чтения</small></div><div class="compact-options">${['A2','B1','B2'].map(level=>`<button class="option-pill ${state.readingLevel===level?'active':''}" data-action="reading-level" data-value="${level}" aria-pressed="${state.readingLevel===level}">${level}</button>`).join('')}</div></div><div class="preference-block reminder-row"><div><strong>Напоминать о занятии</strong><small>${state.profile.reminder?`Каждый день в ${esc(state.profile.reminderTime)}`:'Выключено'}</small></div><button class="switch ${state.profile.reminder?'on':''}" data-action="reminder-toggle" role="switch" aria-checked="${state.profile.reminder}" aria-label="Включить напоминание"><span></span></button></div><button class="account-link" data-action="account-data"><span>${icon('shield')} Данные и приватность</span>${icon('chevron')}</button></section></div></div>`}
function vocabulary(){return `<div class="vocabulary-page"><div class="page-head vocabulary-heading"><div><span class="eyebrow">Личная коллекция</span><h1>Мой словарь</h1><p>${state.words.length} слов — быстро найти, открыть и повторить.</p></div><div class="head-actions"><button class="icon-btn" data-action="import" aria-label="Импортировать слова">${icon('import')}</button><button class="icon-btn dark" data-action="add" aria-label="Добавить слово">${icon('plus')}</button></div></div><section class="vocab-toolbar"><label class="search vocab-search">${icon('search')}<input id="vocab-search" placeholder="Найти слово или перевод" value="${esc(query)}" aria-label="Поиск по словарю"></label><div class="filters vocab-filters" role="group" aria-label="Статус слова">${['All','New','Learning','Weak','Familiar'].map(v=>`<button class="chip ${filter===v?'active':''}" data-action="filter" data-value="${v}" aria-pressed="${filter===v}">${statusLabel(v)}<small>${v==='All'?state.words.length:state.words.filter(w=>w.status===v).length}</small></button>`).join('')}</div></section><div class="vocab-list-head"><div><strong id="word-count"></strong><span>в подборке</span></div><div class="vocab-selects"><label><span>Группа</span><select id="group-filter" aria-label="Группа слов">${['All groups',...new Set(state.words.map(w=>w.group))].map(v=>`<option value="${esc(v)}" ${v===group?'selected':''}>${esc(v==='All groups'?'Все группы':v)}</option>`).join('')}</select></label><label><span>Порядок</span><select id="sort-filter" aria-label="Сортировка слов">${['A–Z','Недавно добавленные','Сначала к повторению'].map(v=>`<option ${v===sort?'selected':''}>${v}</option>`).join('')}</select></label></div></div><div class="vocab-grid" id="vocab-list"></div>${state.words.some(w=>w.status==='New')?`<button class="secondary vocab-review-button" data-action="learn-new">${icon('cards')} Учить новые слова</button>`:''}</div>`}
function renderWords(){if(!$('#vocab-list'))return;const words=state.words.filter(w=>(filter==='All'||w.status===filter)&&(group==='All groups'||w.group===group)&&`${w.word} ${w.translation}`.toLowerCase().includes(query.toLowerCase()));if(sort==='A–Z')words.sort((a,b)=>a.word.localeCompare(b.word,'en'));else if(sort==='Недавно добавленные')words.sort((a,b)=>(b.addedAt||0)-(a.addedAt||0));else words.sort((a,b)=>(a.memory?.dueAt||0)-(b.memory?.dueAt||0));$('#word-count').textContent=words.length;$('#vocab-list').innerHTML=words.length?words.map(wordTile).join(''):`<div class="empty vocab-empty"><h3>Пока ничего</h3><p>Попробуйте другой поиск или добавьте слово.</p><button class="primary" data-action="add">${icon('plus')} Добавить слово</button></div>`}
function startReview(onlyNew=false){let queue=dailyQueue();if(onlyNew)queue=queue.filter(w=>w.status==='New');if(!queue.length){openFreePractice();return}beginSession(queue,'daily')}
function beginSession(queue,mode){session={words:queue.map(w=>({...w})),index:0,flipped:false,answers:[],done:false,mode,retries:{}};closeModal();location.hash='review';if(screen==='review')render();window.scrollTo(0,0)}
function openFreePractice(){modal={type:'free'};showModal('Practice at your own pace.',`<p class="description">Повторяйте сколько хотите. В этом режиме ответы сохраняются отдельно и не сдвигают даты дневного повторения.</p><label class="field-label" for="practice-status">Какие слова?</label><select class="field" id="practice-status">${['All','Weak','Learning','Familiar','New'].map(v=>`<option value="${v}">${v==='All'?'Все слова':v} · ${v==='All'?state.words.length:state.words.filter(w=>w.status===v).length}</option>`).join('')}</select><label class="field-label" for="practice-count">Размер сессии</label><select class="field" id="practice-count"><option value="10">10 слов</option><option value="20">20 слов</option><option value="all">Все выбранные слова</option></select><button class="primary full" style="margin-top:24px" data-action="start-free">Start Practice ${icon('arrow')}</button>`)}
function startFree(){const status=$('#practice-status').value,n=$('#practice-count').value;const queue=state.words.filter(w=>status==='All'||w.status===status);for(let i=queue.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[queue[i],queue[j]]=[queue[j],queue[i]]}if(!queue.length){toast('В этой группе пока нет слов');return}beginSession(queue.slice(0,n==='all'?queue.length:Number(n)),'free')}
function answerCurrent(rating){if(!session||session.done||!session.flipped)return;const old=state.words.find(w=>w.id===session.words[session.index].id),mode=session.mode||'daily',now=Date.now();const next=MemoryModel.answer(old,rating,mode,now);state.words[state.words.indexOf(old)]=next;state.reviewed.push({id:old.id,day:todayKey(),at:now,answer:rating,mode});session.answers.push(rating);if(mode==='daily'&&rating==='Forgot'&&(session.retries[old.id]||0)<1){session.retries[old.id]=(session.retries[old.id]||0)+1;session.words.splice(Math.min(session.words.length,session.index+4),0,{...next})}session.index++;session.flipped=false;session.done=session.index>=session.words.length;persist();render()}
function nextReviewLabel(w){const delta=w.memory.dueAt-Date.now();return delta<=0?'Пора повторить':delta<3600000?'Повторение через 10 мин':`Следующее повторение: ${new Date(w.memory.dueAt).toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}`}
function answerInterval(w,rating){if(session.mode==='free')return 'Без переноса даты';const n=MemoryModel.answer(w,rating,'daily');return rating==='Forgot'?'Ещё раз в сессии':`Через ${Math.max(1,Math.round((n.memory.dueAt-Date.now())/MemoryModel.DAY))} дн.`}
function review(){if(!session)return `<div class="empty"><h1>Ready for a little practice?</h1><p>Короткая сессия с вашими словами.</p><button class="primary" data-action="review">Start Review ${icon('arrow')}</button></div>`;const s=session;if(s.done){return `<div class="review-page"><div class="session-done"><div class="success-symbol">${icon('check')}</div><span class="eyebrow">A little more familiar</span><h1>Nicely done.</h1><p>Вы дали ${s.answers.length} ответов.<br>${s.mode==='free'?'Свободная практика завершена. Расписание сохранено.':'Одного ответа мало: слова вернутся через время.'}</p><div class="import-summary">${[['Forgot',s.answers.filter(a=>a==='Forgot').length],['Hard',s.answers.filter(a=>a==='Hard').length],['Recalled',s.answers.filter(a=>a==='Know').length]].map(([l,n])=>`<div><strong>${n}</strong><small>${l}</small></div>`).join('')}</div><button class="primary full" data-action="read-today">Meet your words again ${icon('arrow')}</button><button class="secondary full" style="margin-top:12px" data-action="free-review">Practice more</button><a class="text-btn" style="justify-content:center;margin-top:18px" href="#today">Back to Today</a></div></div>`}const w=state.words.find(w=>w.id===s.words[s.index].id);return `<div class="review-page"><div class="review-toolbar"><button class="icon-btn" data-action="leave-review" aria-label="Exit review">${icon('close')}</button><span class="eyebrow">${s.mode==='free'?'Free practice':'Daily review'}</span><span class="muted">${s.index+1} / ${s.words.length}</span></div><div class="progress" role="progressbar" aria-valuenow="${s.index}" aria-valuemin="0" aria-valuemax="${s.words.length}" aria-label="Review progress"><span style="width:${s.index/s.words.length*100}%"></span></div><div class="flashcard"><span class="eyebrow">${esc(w.group)}</span><h1>${esc(w.word)}</h1><p class="pronunciation">${esc(w.ipa)} · ${esc(w.pos)}</p>${s.flipped?`<p class="translation">${esc(w.translation)}</p><p class="example">${esc(w.example)}</p>`:`<p class="hint" style="margin-top:35px">Вспомните значение. Не торопитесь.</p>`}</div>${s.flipped?`<div class="review-controls">${[['Forgot','Забыл'],['Hard','С трудом'],['Know','Вспомнил']].map(([v,l])=>`<button data-action="answer" data-value="${v}">${v==='Know'?'Recalled':v}<small>${l} · ${answerInterval(w,v)}</small></button>`).join('')}</div>`:`<button class="primary full" style="margin-top:28px" data-action="flip">Show Answer ${icon('arrow')}</button>`}<p class="footer-note">${s.mode==='free'?'Свободная практика не меняет расписание и статус.':s.flipped?'Вспомнили сейчас. Проверим снова через время.':'Попробуйте вспомнить до того, как перевернёте карточку.'}</p></div>`}
function articleWords(a){const body=a.paragraphs.join(' ').toLowerCase();return state.words.filter(w=>new RegExp(`\\b${w.word.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\b`,'i').test(body))}
function getArticle(key){return state.readingLevel==='B1'?ARTICLES[key]:READING_LEVELS[state.readingLevel][key]}
function readingMinutes(a){const words=a.paragraphs.join(' ').split(/\s+/).length;return Math.max(1,Math.ceil(words/({'A2':80,'B1':110,'B2':140}[state.readingLevel])))}
function selectedArticles(){const keys=[topic,...Object.keys(ARTICLES).filter(t=>t!==topic)];return keys.slice(0,duration===5?1:duration===10?2:3).map(getArticle)}
function reading(){if(articleOpen)return reader();return `<div class="page-head"><div><h1>Meet your words<br>again.</h1><p>Знакомые слова. Новые истории.</p></div><span class="round-symbol">${icon('spark')}</span></div><section class="reader-cover"><span class="eyebrow">Made for your vocabulary</span><h1>${getArticle(topic).title}</h1><p>${getArticle(topic).intro}</p><p class="meta" style="margin-top:18px">${state.readingLevel} · ${articleWords(getArticle(topic)).length} of your words</p></section><section class="reading-options"><label class="field-label">Уровень текста</label><div class="filters" role="group" aria-label="Reading level">${['A2','B1','B2'].map(l=>`<button class="chip ${state.readingLevel===l?'active':''}" aria-pressed="${state.readingLevel===l}" data-action="reading-level" data-value="${l}">${l}</button>`).join('')}</div><p class="hint">${{A2:'Простые предложения, знакомые ситуации, объяснение сложных слов.',B1:'Связный текст на интересную тему, умеренная сложность.',B2:'Более точная лексика, аргументы и сложные связи между идеями.'}[state.readingLevel]}</p><label class="field-label">Что вам интересно?</label><div class="filters">${Object.keys(ARTICLES).map(t=>`<button class="chip ${t===topic?'active':''}" data-action="topic" data-value="${t}">${t}</button>`).join('')}</div><label class="field-label">Сколько времени у вас есть?</label><div class="filters">${[5,10,15].map(n=>`<button class="chip ${duration===n?'active':''}" data-action="duration" data-value="${n}">${n} min</button>`).join('')}</div><p class="hint">${duration===5?'Одна история':duration===10?'Две истории: выбранная тема и новый взгляд':'Три истории из вашей подборки'} · ваши слова выделены в тексте.</p><button class="primary full" data-action="read">Start Reading ${icon('arrow')}</button></section><p class="footer-note">Авторские адаптации A2–B2 · уровень ориентировочный</p>`}
function tokenize(text){return text.split(/([a-zA-Z]+(?:['’][a-zA-Z]+)?)/g).map(token=>{if(!/^[a-zA-Z]/.test(token))return esc(token);const w=lookup(token);const tracked=state.words.find(x=>x.word.toLowerCase()===token.toLowerCase());return `<button class="inline-word ${tracked?'':'untracked'}" data-action="reading-word" data-value="${esc(token.toLowerCase())}" aria-label="Перевод: ${esc(token)}">${esc(token)}</button>`}).join('')}
function reader(){const articles=selectedArticles();return `<div class="article"><div class="review-toolbar"><button class="icon-btn" data-action="reading-back" aria-label="Back to reading topics">${icon('back')}</button><span class="eyebrow">Your reading time</span><span class="meta">${duration} min</span></div>${articles.map((a,i)=>`<section><div class="reader-cover"><span class="eyebrow">${i+1} / ${articles.length} · ${a.eyebrow}</span><h1>${a.title}</h1><p>${a.intro}</p><p class="meta" style="margin-top:18px">${state.readingLevel} · ~${readingMinutes(a)} min · ${articleWords(a).length} words from your vocabulary</p></div>${i===0?'<p class="article-hint"><i></i>Выделены ваши слова. Нажмите на слово для перевода.</p>':''}<div class="article-body">${a.paragraphs.map(p=>`<p>${tokenize(p)}</p>`).join('')}</div></section>`).join('')}<section class="reader-footer"><h3>One more meeting. One step closer.</h3><p>Вы встретили знакомые слова в новой истории. Так они становятся частью вашего английского.</p><button class="primary full" data-action="finish-reading">${icon('check')} Finish reading</button></section></div>`}
const phrasebook={"you're bound by nothing.":'Вы ничем не связаны.',"you're bound by nothing":'Вы ничем не связаны.',"you are bound by nothing":'Вы ничем не связаны.',"i am reluctant to admit it":'Я неохотно это признаю.',"he was reluctant to admit his mistake.":'Он не хотел признавать свою ошибку.',"small steps make a difference":'Маленькие шаги имеют значение.',"я неохотно это признаю":'I am reluctant to admit it.',"маленькие шаги имеют значение":'Small steps make a difference.',"вы ничем не связаны":'You’re bound by nothing.'};
function translator(){return `<div class="page-head"><div><h1>A word. A thought.</h1><p>Переведите — и сохраните нужное.</p></div></div><div class="translator-box"><div class="language-bar"><span>${language==='en'?'English':'Русский'}</span><button class="icon-btn" style="height:34px;width:34px" data-action="swap" aria-label="Swap languages">${icon('swap')}</button><span>${language==='en'?'Русский':'English'}</span></div><textarea id="translate-input" aria-label="Text to translate" placeholder="${language==='en'?'A word or a sentence…':'Слово или предложение…'}" maxlength="1000">${esc(translateInput)}</textarea><button class="primary" data-action="translate">Translate ${icon('arrow')}</button></div>${translationResult?`<div class="translation-result"><span class="eyebrow">${translationResult.error?'Try another phrase':'Translation'}</span><p class="translation">${esc(translationResult.text)}</p>${translationResult.word?`<p class="pronunciation">${esc(translationResult.word.ipa)} · ${esc(translationResult.word.pos)}</p><p style="font-size:15px;line-height:1.7;margin:16px 0">${esc(translationResult.word.example)}</p><button class="secondary full" data-action="save-translation" ${state.words.some(w=>w.id===translationResult.word.id)?'disabled':''}>${icon(state.words.some(w=>w.id===translationResult.word.id)?'check':'plus')}${state.words.some(w=>w.id===translationResult.word.id)?'In your Vocabulary':'Add to Vocabulary'}</button>`:''}</div>`:''}<div class="section-title"><h2>Try a translation</h2></div><div class="suggestions">${(language==='en'?['bound',"You’re bound by nothing.",'reluctant','Small steps make a difference']:['вы ничем не связаны','привычка','уверенность']).map(v=>`<button class="chip" data-action="translation-example" data-value="${esc(v)}">${esc(v)}</button>`).join('')}</div><p class="footer-note">Демо: ${DICTIONARY.length} слов и несколько фраз.<br>Свободный перевод появится после подключения сервиса.</p>`}
function render(){shell(screen==='today'?today():screen==='vocabulary'?vocabulary():screen==='review'?review():screen==='reading'?reading():screen==='profile'?profile():translator());if(screen==='vocabulary')renderWords();if(screen==='profile')requestAnimationFrame(()=>{const calendar=$('#activity-scroll');if(calendar)calendar.scrollLeft=calendar.scrollWidth})}
function definition(w,editable=false){return `<div class="definition"><div class="card-top"><h2>${esc(w.word)}</h2>${state.words.some(x=>x.id===w.id)?badge(state.words.find(x=>x.id===w.id).status):''}</div><p class="pronunciation">${esc(w.ipa)}${w.ipa?' · ':''}${esc(w.pos)}</p><p class="translation">${esc(w.translation)}</p>${w.example?`<p class="example"><small>IN CONTEXT</small>${esc(w.example)}</p>`:''}${editable?`<div class="memory-summary"><span class="field-label">${nextReviewLabel(w)}</span><p>${w.memory.successfulDays.length} успешных дней · ${w.memory.lapses} забываний</p><small>Статус меняется по повторениям через время. Familiar — устойчивое узнавание, не «выучено навсегда».</small></div><label class="field-label" for="word-group">Группа</label><select id="word-group" data-id="${esc(w.id)}">${[...new Set(['Everyday','Mind & life','Travel','Work','Imported',w.group])].map(g=>`<option ${w.group===g?'selected':''}>${esc(g)}</option>`).join('')}</select>`:''}</div>`}
function showModal(title,body){lastFocus=document.activeElement;$('#overlays').innerHTML=`<div class="modal-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></header>${body}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>($('.sheet input')||$('.sheet')).focus())}
function closeModal(){modal=null;$('#overlays').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
function editProfile(){modal={type:'profile'};showModal('Настройки профиля',`<p class="description">Имя отображается только в вашем личном кабинете.</p><form id="profile-form"><label class="field-label" for="profile-name">Как к вам обращаться?</label><input class="field" id="profile-name" maxlength="40" autocomplete="name" value="${esc(state.profile.name)}"><label class="field-label" for="reminder-time">Время напоминания</label><input class="field" id="reminder-time" type="time" value="${esc(state.profile.reminderTime)}"><button class="primary full" style="margin-top:24px">Сохранить ${icon('check')}</button></form>`)}
function quickAdd(value=''){modal={type:'add'};showModal('One word, a new beginning.',`<p class="description">Введите английское слово — перевод и пример уже готовы.</p><form id="add-form"><label class="search">${icon('search')}<input id="add-input" placeholder="Try “reluctant”" autocomplete="off" value="${esc(value)}" aria-label="Word to add"><button class="icon-btn dark" style="width:34px;height:34px" aria-label="Look up word">${icon('arrow')}</button></label></form><div id="add-result"></div><p class="hint">Попробуйте: reluctant, overwhelmed, embrace, serendipity.</p>`);if(value)searchAdd()}
function searchAdd(){const value=$('#add-input').value.trim();const w=lookup(value);modal.word=w;if(!value){$('#add-result').innerHTML='';return}$('#add-result').innerHTML=w?`${definition(w)}<button class="primary full" data-action="save-word" ${state.words.some(x=>x.id===w.id)?'disabled':''}>${icon(state.words.some(x=>x.id===w.id)?'check':'plus')} ${state.words.some(x=>x.id===w.id)?'Already in Vocabulary':'Add to Vocabulary'}</button>`:`<div class="empty" style="padding:25px 0"><h3>Этого слова пока нет в демо</h3><p>Попробуйте reluctant или импортируйте слово со своим переводом.</p></div>`}
function addWord(w){if(state.words.some(x=>x.word.toLowerCase()===w.word.toLowerCase()))return false;state.words.unshift({...w,status:'New',memory:MemoryModel.initial(),addedAt:Date.now()});persist();return true}
function openWord(w,fromReading=false){modal={type:'word',word:w};const tracked=state.words.find(x=>x.id===w.id);showModal(fromReading?'A word in your story':'Your word',`${definition(tracked||w,!!tracked)}${tracked?`<p class="hint">${fromReading?'Вы снова встретили своё слово — уже в контексте.':'New → Learning → Familiar. При забывании — Weak.'}</p>${tracked.status==='New'?'<button class="primary full" data-action="learn-this">Learn this word '+icon('arrow')+'</button>':''}`:`<button class="primary full" data-action="save-word">${icon('plus')} Add to Vocabulary</button>`}`)}
function showImport(mode='paste'){importMode=mode;importPreview=null;modal={type:'import'};showModal('Bring your words along.',`<p class="description">Ваш словарь уже где-то есть. Перенесём его сюда.</p><div class="import-options">${[['xlsx','Excel'],['csv','CSV'],['paste','Paste List']].map(([id,label])=>`<button class="import-option ${mode===id?'active':''}" data-action="import-mode" data-value="${id}">${icon(id==='paste'?'cards':'file')}${label}</button>`).join('')}</div><div id="import-content">${mode==='paste'?`<label class="field-label" for="paste-list">Одно слово в строке · перевод через ; или Tab</label><textarea class="field" id="paste-list" placeholder="reluctant; неохотный&#10;embrace; принимать&#10;familiar; знакомый"></textarea><button class="text-btn" data-action="paste-example">Вставить пример</button><button class="primary full" style="margin-top:18px" data-action="analyze-paste">Preview import ${icon('arrow')}</button>`:`<label class="field-label" for="import-file">${mode==='xlsx'?'Файл .xlsx / .xls':'Файл .csv'}</label><input class="field" type="file" id="import-file" accept="${mode==='xlsx'?'.xlsx,.xls':'.csv,text/csv'}"><p class="hint">${mode==='xlsx'?'В прототипе Excel показывает демонстрационный импорт. Содержимое файла не загружается на сервер.':'Столбцы: word и translation. Разделитель: запятая, точка с запятой или Tab. До 2 МБ.'}</p><button class="secondary full" data-action="demo-import">Try a sample ${mode==='xlsx'?'Excel':'CSV'} file ${icon('arrow')}</button>`}</div>`)}
function parseDelimited(text){text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0];const delimiter=first.includes('\t')?'\t':first.includes(';')?';':',';const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===delimiter&&!quoted){row.push(cell.trim());cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows}
function analyzeImport(text,isDemo=false){let rows=parseDelimited(text);if(rows.length&&/^(word|english|слово)$/i.test(rows[0][0]))rows.shift();const seen=new Set(state.words.map(w=>w.word.toLowerCase())),ready=[],skipped=[],duplicates=[];for(const row of rows){const name=(row[0]||'').trim().toLowerCase(),known=lookup(name);if(!/^[a-z][a-z\s'’-]{0,79}$/i.test(name)){skipped.push(row.join(' — '));continue}if(seen.has(name)){duplicates.push(name);continue}const translation=row[1]||known?.translation;if(!translation){skipped.push(name);continue}seen.add(name);ready.push(known?{...known,translation}:{id:name,word:name,translation,ipa:'',pos:'word / phrase',example:'',group:'Imported',status:'New'})}importPreview={ready,skipped,duplicates,total:rows.length,isDemo};showImportPreview()}
function showImportPreview(){const p=importPreview;modal={type:'import-preview'};showModal('Your words, almost home.',`<span class="pill">${p.isDemo?'Демонстрационный файл':'Предпросмотр импорта'}</span><h2 style="font-size:36px;margin-top:22px">${p.total} words detected</h2><div class="import-summary"><div><strong>${p.ready.length}</strong><small>Ready to import</small></div><div><strong>${p.duplicates.length}</strong><small>Duplicates</small></div><div><strong>${p.skipped.length}</strong><small>Need attention</small></div></div>${p.ready.length?`<div class="word-list">${p.ready.slice(0,3).map(w=>`<div class="word-row"><span class="word-info"><strong>${esc(w.word)}</strong><p>${esc(w.translation)}</p></span>${badge('New')}</div>`).join('')}</div>`:''}${p.duplicates.length?`<p class="hint">Уже в словаре: ${esc(p.duplicates.slice(0,8).join(', '))}${p.duplicates.length>8?'…':''}.</p>`:''}${p.skipped.length?`<p class="hint">Пропускаем без перевода или с неверным форматом: ${esc(p.skipped.slice(0,5).join(', '))}. Можно исправить список и попробовать снова.</p>`:''}<button class="primary full" style="margin-top:23px" data-action="confirm-import" ${p.ready.length?'':'disabled'}>Import ${p.ready.length} words ${icon('arrow')}</button><button class="text-btn" style="margin:12px auto 0" data-action="import-back">Back to import</button>`)}
function route(){const target=location.hash.slice(1);screen=['today','vocabulary','reading','translator','review','profile'].includes(target)?target:'today';closeModal();render();window.scrollTo(0,0)}
document.addEventListener('input',e=>{if(e.target.id==='vocab-search'){query=e.target.value;renderWords()}if(e.target.id==='add-input'){clearTimeout(searchAdd.timer);searchAdd.timer=setTimeout(()=>{if(modal?.type==='add')searchAdd()},180)}if(e.target.id==='translate-input')translateInput=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id==='add-form'){e.preventDefault();searchAdd()}if(e.target.id==='profile-form'){e.preventDefault();const name=$('#profile-name').value.trim();if(!name){toast('Введите имя');return}state.profile.name=name;state.profile.reminderTime=$('#reminder-time').value||'19:00';persist();closeModal();render();toast('Личное пространство обновлено')}});
document.addEventListener('change',async e=>{if(e.target.id==='group-filter'){group=e.target.value;renderWords()}if(e.target.id==='sort-filter'){sort=e.target.value;renderWords()}if(e.target.id==='word-group'){const w=state.words.find(w=>w.id===e.target.dataset.id);w.group=e.target.value;persist();render();toast('Слово обновлено')}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024){toast('Для прототипа выберите файл до 2 МБ');e.target.value='';return}if(importMode==='xlsx'){analyzeImport(sampleImport(),true)}else{try{analyzeImport(await file.text())}catch{toast('Не удалось прочитать файл. Попробуйте Paste List.')}}}});
function sampleImport(){return 'word;translation\nreluctant;неохотный\nembrace;принимать\nserendipity;счастливая случайность\nresilient;стойкий\noverwhelmed;перегруженный\nconfidence;уверенность\nhabit;привычка\nuncertainty;неопределённость\nfamiliar;знакомый\ndespite;несмотря на\n123;\nunknownterm;'}
function doTranslate(){const val=translateInput.trim().toLowerCase().replace(/’/g,"'");if(!val){toast('Введите слово или фразу');return}const w=language==='en'?lookup(val):DICTIONARY.find(w=>w.translation.split(';').some(t=>t.trim().toLowerCase()===val));translationResult=w?{text:language==='en'?w.translation:w.word,word:w}:phrasebook[val]?{text:phrasebook[val]}:{text:'В демо пока нет этого перевода. Выберите пример ниже.',error:true};render()}
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop')){closeModal();return}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,v=b.dataset.value;
if(a==='add')quickAdd();else if(a==='edit-profile')editProfile();else if(a==='activity-range'){state.profile.activityWeeks=Number(v);persist();render()}else if(a==='daily-goal'){state.profile.dailyGoal=Number(v);persist();render();toast(`Дневная цель: ${v} слов`)}else if(a==='reminder-toggle'){state.profile.reminder=!state.profile.reminder;persist();render();toast(state.profile.reminder?`Напоминание включено на ${state.profile.reminderTime}`:'Напоминание выключено')}else if(a==='account-data')toast('Настройки приватности появятся после подключения аккаунта');else if(a==='close')closeModal();else if(a==='word')openWord(wordById(b.dataset.id));else if(a==='filter'){filter=v;render()}else if(a==='save-word'){if(addWord(modal.word)){closeModal();render();toast('Added to Vocabulary · готово к изучению')}}else if(a==='review')startReview();else if(a==='learn-new')startReview(true);else if(a==='learn-this'){const w=modal.word;if(dailyRemaining()>0)beginSession([w],'daily');else openFreePractice()}else if(a==='flip'){session.flipped=true;render()}else if(a==='answer')answerCurrent(v);else if(a==='free-review')openFreePractice();else if(a==='start-free')startFree();else if(a==='leave-review'){modal={type:'leave'};showModal('Продолжим позже?',`<p class="description">Ответы уже сохранены. Можно закончить сейчас или вернуться к следующей карточке.</p><button class="primary full" data-action="close">Continue review</button><button class="secondary full" style="margin-top:12px" data-action="exit-review">Back to Today</button>`)}else if(a==='exit-review'){closeModal();location.hash='today'}else if(a==='read-today'){topic='Mind & life';duration=5;articleOpen=true;location.hash='reading';if(screen==='reading'){render();window.scrollTo(0,0)}}else if(a==='read'){articleOpen=true;render();window.scrollTo(0,0)}else if(a==='reading-back'){articleOpen=false;render();window.scrollTo(0,0)}else if(a==='topic'){topic=v;render()}else if(a==='reading-level'){state.readingLevel=v;persist();render()}else if(a==='duration'){duration=Number(v);render()}else if(a==='reading-word'){const w=lookup(v)||readingGlossary(v);if(w)openWord(w,true);else{modal={type:'unavailable'};showModal(esc(v),`<p class="description">Для этого слова в демо пока нет перевода. Нажмите на выделенное слово или попробуйте reluctant, memory, evidence.</p><button class="secondary full" data-action="close">Back to reading</button>`)}}else if(a==='finish-reading'){state.read.push({topic,level:state.readingLevel,date:todayKey(),wordIds:[...new Set(selectedArticles().flatMap(a=>articleWords(a).map(w=>w.id)))]});persist();articleOpen=false;location.hash='today';toast('Reading complete · ещё одна встреча с вашими словами')}else if(a==='import')showImport();else if(a==='import-mode')showImport(v);else if(a==='paste-example')$('#paste-list').value=sampleImport();else if(a==='analyze-paste'){const val=$('#paste-list').value;if(!val.trim()){toast('Вставьте список слов');return}analyzeImport(val)}else if(a==='demo-import')analyzeImport(sampleImport(),true);else if(a==='import-back')showImport(importMode);else if(a==='confirm-import'){const p=importPreview;for(const w of p.ready)addWord(w);modal={type:'import-success'};showModal('Your vocabulary is here.',`<div class="success-symbol">${icon('check')}</div><h2 class="center">${p.ready.length} words imported</h2><p class="description center" style="margin-top:16px">${p.duplicates.length} дублей · ${p.skipped.length} пропущено<br>Новые слова ждут первой встречи.</p><button class="primary full" data-action="view-import">Open Vocabulary ${icon('arrow')}</button>`);render()}else if(a==='view-import'){filter='New';query='';group='All groups';closeModal();location.hash='vocabulary';if(screen==='vocabulary')render()}else if(a==='translate')doTranslate();else if(a==='translation-example'){translateInput=v;doTranslate()}else if(a==='swap'){language=language==='en'?'ru':'en';translateInput='';translationResult=null;render()}else if(a==='save-translation'){if(addWord(translationResult.word)){render();toast('Added to Vocabulary')}}});
const EXTRA_GLOSSARY={brain:'мозг',recognition:'узнавание; распознавание',layout:'планировка',arrangement:'расположение',retrieve:'извлекать; вспоминать',sensation:'ощущение',similarity:'сходство',extraordinary:'необыкновенный',observe:'наблюдать',recognise:'узнавать',predicted:'предсказал',store:'хранить',details:'детали',explanation:'объяснение',easily:'легко',waiting:'ожидание',bakery:'пекарня',receipt:'чек',surroundings:'окружение',permission:'разрешение',inspiration:'вдохновение',cue:'сигнал; подсказка',repetition:'повторение',failure:'неудача',negotiation:'переговоры',ordinary:'обычный',useful:'полезный',quietly:'тихо',language:'язык',certain:'уверенный',difficult:'трудный',experience:'опыт; переживание',connection:'связь',child:'ребёнок',childhood:'детство',because:'потому что',although:'хотя',quickly:'быстро',strange:'странный',familiarity:'чувство знакомого',remembering:'вспоминание',event:'событие',doorway:'дверной проём',light:'свет',demand:'требование; запрос',outstanding:'выдающийся',before:'до; перед',after:'после',between:'между',feeling:'ощущение',happened:'случилось',memory:'память'};
function readingGlossary(v){if(!EXTRA_GLOSSARY[v])return null;const para=selectedArticles().flatMap(a=>a.paragraphs).find(p=>p.toLowerCase().includes(v));const sentence=para?.split(/(?<=[.!?])\s+/).find(s=>s.toLowerCase().includes(v));return {id:v,word:v,translation:EXTRA_GLOSSARY[v],ipa:'',pos:'in this context',example:sentence||'',status:'New',group:'Reading'}}
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const items=[...document.querySelectorAll('.sheet button:not(:disabled),.sheet input,.sheet textarea,.sheet select,.sheet a')];const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.sheet'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',route);route();
